842	func (r *renderer) addArg(value any) string {
843		r.placeholderCounter++
844		r.args = append(r.args, value)
845		if r.dialect == DialectPostgres {
846			return fmt.Sprintf("$%d", r.placeholderOffset+r.placeholderCounter)
847		}
848		return "?"
849	}
850	
851	func (r *renderer) addBoolArg(value bool) string {
852		var v any
853		switch r.dialect {
854		case DialectSQLite:
855			if value {
856				v = 1
